      hu: ["Több mint 60 ipari létesítmény a régióban", "Kanada vegyipari termékeinek 40%-át adja", "Itt fúrták az első olajkutat (1858)", "Az Enbridge Line 5 csővezeték központja", "Jelentős szintetikus gumi gyártás", "A polimer export meghatározó helyszíne"],
      ro: ["Peste 60 de instalații industriale în regiune", "Produce 40% din produsele chimice canadiene", "Primul puț de petrol comercial (1858)", "Hub pentru conducta Enbridge Line 5", "Producție majoră de cauciuc sintetic", "Locație majoră de export pentru polimeri"],
      en: ["Over 60 industrial facilities in the region", "Produces 40% of Canada's chemical products", "First commercial oil well in NA (1858)", "Hub for the Enbridge Line 5 pipeline", "Major production of synthetic rubber", "Key export location for polymers"],
      es: ["Número de empresas: más de 20", "Empleados: más de 5.000", "Año de fundación: década de 1940", "Productos principales: etileno, propileno, benceno, polietileno", "Ubicación: orillas del lago Hurón", "Conexión por oleoducto: desde el oeste de Canadá"],
      pt: ["Número de empresas: mais de 20", "Funcionários: mais de 5.000", "Ano de fundação: década de 1940", "Principais produtos: etileno, propileno, benzeno, polietileno", "Localização: margens do Lago Huron", "Conexão por oleoduto: vindo do oeste do Canadá"],
      fr: ["Nombre d'entreprises : plus de 20", "Employés : plus de 5 000", "Année de fondation : années 1940", "Principaux produits : éthylène, propylène, benzène, polyéthylène", "Situation : rives du lac Huron", "Raccordement par pipeline : depuis l'Ouest canadien"],
